cases.setup_script:
[[ $UID == 2000 && $EUID == 2000 && $PWD == /tmp/parity-case && $HOME == /tmp/parity-home && -O /tmp/parity-case && -O /tmp/parity-home && -r /etc/bashos-parity-vm && -r /sys/class/dmi/id/sys_vendor ]] || { echo 'not a disposable parity guest' >&2; exit 98; }
marker=$(< /etc/bashos-parity-vm); vendor=$(< /sys/class/dmi/id/sys_vendor)
[[ $marker =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ && $vendor == QEMU ]] || { echo 'guest identity mismatch' >&2; exit 98; }
/usr/bin/cp /opt/bashos-parity/harness/helpers/services-lpr.py "$HOME/backend"
/usr/bin/chmod 700 "$HOME/backend"
/usr/bin/mkdir -m 700 "$HOME/spool"
LPR_FIXTURE_MODE=control "$HOME/backend" 0123456789abcdef 6 proof < control-input > "$HOME/control.out" 2> "$HOME/control.err"
"$HOME/backend" --check control > "$HOME/control.check"
[[ $(< "$HOME/control.check") == 'control-observation=ok' && ! -s $HOME/control.out && ! -s $HOME/control.err ]] || { echo 'CONTROL-FAILED print backend' >&2; exit 98; }

